import React, { useCallback, useEffect, useState } from "react";

import { API_URL } from "../apiConfig";
import { apiRequest } from "./DeliveryShared";

export default function DeliveryChatSheet({ deliveryId, role = "customer", onClose }) {
  const [templates, setTemplates] = useState([]);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    if (!deliveryId) return;
    setLoading(true);
    setError("");
    try {
      const [templateData, messageData] = await Promise.all([
        apiRequest(`${API_URL}/deliveries/${deliveryId}/chat/templates/`),
        apiRequest(`${API_URL}/deliveries/${deliveryId}/chat/`),
      ]);
      setTemplates(Array.isArray(templateData?.templates) ? templateData.templates : []);
      setMessages(Array.isArray(messageData) ? messageData : []);
    } catch (err) {
      setError(err.message || "Could not load chat.");
    } finally {
      setLoading(false);
    }
  }, [deliveryId]);

  useEffect(() => {
    load();
    const intervalId = window.setInterval(load, 8000);
    return () => window.clearInterval(intervalId);
  }, [load]);

  const sendTemplate = async (templateKey) => {
    if (!deliveryId || sending) return;
    setSending(true);
    setError("");
    try {
      await apiRequest(`${API_URL}/deliveries/${deliveryId}/chat/send/`, {
        method: "POST",
        body: JSON.stringify({ template_key: templateKey }),
      });
      await load();
    } catch (err) {
      setError(err.message || "Could not send message.");
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="delivery-chat-sheet">
      <div className="delivery-chat-sheet__head">
        <div>
          <strong>Quick messages</strong>
          <span>Template replies only</span>
        </div>
        <button type="button" className="delivery-chat-sheet__close" onClick={onClose} aria-label="Close chat">
          ×
        </button>
      </div>

      {error ? <div className="delivery-chat-sheet__error">{error}</div> : null}

      <div className="delivery-chat-sheet__messages">
        {loading && messages.length === 0 ? (
          <p className="delivery-chat-sheet__empty">Loading messages...</p>
        ) : null}
        {!loading && messages.length === 0 ? (
          <p className="delivery-chat-sheet__empty">No messages yet. Tap a template below.</p>
        ) : null}
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`delivery-chat-sheet__bubble ${msg.is_mine ? "is-mine" : "is-theirs"}`}
          >
            <span>{msg.text}</span>
          </div>
        ))}
      </div>

      <div className="delivery-chat-sheet__templates">
        {templates.map((item) => (
          <button
            key={item.key}
            type="button"
            className="delivery-chat-sheet__template"
            disabled={sending}
            onClick={() => sendTemplate(item.key)}
          >
            {item.text}
          </button>
        ))}
      </div>
    </div>
  );
}
