import React, { useCallback, useEffect, useState } from "react";

import { API_URL } from "../apiConfig";
import { DeliveryUberPage } from "./DeliveryUberLayout";
import { apiRequest } from "./DeliveryShared";
import "./delivery-uber.css";

export default function DeliveryHistory() {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const data = await apiRequest(`${API_URL}/deliveries/courier/earnings/`);
      setHistory(data?.history || []);
    } catch (err) {
      setError(err.message || "Could not load delivery history.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <DeliveryUberPage title="Delivery history" onBack={() => (window.location.href = "/delivery/courier")}>
      <div className="delivery-uber__history-list">
        {error ? <p className="delivery-uber__toast is-error">{error}</p> : null}
        {loading ? <p className="delivery-uber__empty">Loading delivery history...</p> : null}
        {!loading && history.length === 0 ? (
          <p className="delivery-uber__empty">No completed deliveries yet.</p>
        ) : null}
        {history.map((delivery) => (
          <article key={delivery.id} className="delivery-uber__history-item">
            <div>
              <strong>Delivery #{delivery.id}</strong>
              <p>{delivery.pickup} to {delivery.destination}</p>
              <p>{delivery.service_city || "Nouakchott"}</p>
            </div>
            <div className="delivery-uber__history-meta">
              <strong>{Number(delivery.driver_earning || delivery.fare || 0).toFixed(0)} MRU</strong>
              <span>{delivery.status || "delivered"}</span>
            </div>
          </article>
        ))}
      </div>
    </DeliveryUberPage>
  );
}
