import React, { useState } from "react";

import DeliveryCourierMenu from "./DeliveryCourierMenu";
import DeliveryMapBackdrop from "./DeliveryMapBackdrop";
import { isDeliveryUberUI } from "../native/platform";
import "./delivery-uber.css";
import "./delivery-premium-ui.css";
import "./delivery-courier-dashboard.css";

export function DeliveryUberPage({ title, onBack, children }) {
  if (!isDeliveryUberUI()) {
    return <div className="delivery-page">{children}</div>;
  }

  return (
    <div className="delivery-uber-page">
      <header className="delivery-uber-page__header">
        {onBack ? (
          <button type="button" className="delivery-uber__icon-btn" onClick={onBack} aria-label="Back">
            ←
          </button>
        ) : (
          <span className="delivery-uber-page__header-spacer" />
        )}
        <h1>{title}</h1>
      </header>
      <div className="delivery-uber-page__content">{children}</div>
    </div>
  );
}

export function DeliveryCourierShell(props) {
  return <DeliveryUberShell {...props} courierMode />;
}

export function DeliveryUberShell({
  statusOnline,
  notice,
  error,
  onRefresh,
  sheetTitle,
  sheetSubtitle,
  sheetHead,
  children,
  showNav = true,
  activeNav = "home",
  activeDelivery = null,
  earningsLabel = "",
  todayEarnings = null,
  courierMode = false,
}) {
  const [menuOpen, setMenuOpen] = useState(false);
  const shellClass = courierMode ? "delivery-uber delivery-uber--courier" : "delivery-uber";

  return (
    <main className={shellClass}>
      <DeliveryMapBackdrop activeDelivery={activeDelivery} />
      <DeliveryCourierMenu open={menuOpen} onClose={() => setMenuOpen(false)} />

      <div className="delivery-uber__top">
        {courierMode ? (
          <div className="delivery-uber__top-bar">
            <button
              type="button"
              className="delivery-uber__icon-btn"
              onClick={() => setMenuOpen(true)}
              aria-label="Open delivery menu"
            >
              ☰
            </button>
            <div className="delivery-uber__top-brand">
              <img src="/yala-delivery-logo.png" alt="" />
              <strong>Yala Delivery</strong>
              <span>Courier dashboard</span>
            </div>
            <button type="button" className="delivery-uber__icon-btn" onClick={onRefresh} aria-label="Refresh">
              ↻
            </button>
          </div>
        ) : (
          <>
            <button
              type="button"
              className="delivery-uber__icon-btn"
              onClick={() => setMenuOpen(true)}
              aria-label="Open menu"
            >
              ☰
            </button>
            <div className="delivery-uber__top-center">
              <span className={`delivery-uber__status-pill ${statusOnline ? "is-online" : "is-offline"}`}>
                {statusOnline ? "Online" : "Offline"}
              </span>
              {earningsLabel ? <span className="delivery-uber__earnings-pill">{earningsLabel}</span> : null}
            </div>
            <button type="button" className="delivery-uber__icon-btn" onClick={onRefresh} aria-label="Refresh">
              ↻
            </button>
          </>
        )}
      </div>

      {courierMode ? (
        <div className="delivery-uber__top-center delivery-uber__top-center--courier">
          <span className={`delivery-uber__status-pill ${statusOnline ? "is-online" : "is-offline"}`}>
            {statusOnline ? "Online for deliveries" : "Offline"}
          </span>
          {earningsLabel ? <span className="delivery-uber__earnings-pill">{earningsLabel}</span> : null}
        </div>
      ) : null}

      {notice ? <div className="delivery-uber__toast">{notice}</div> : null}
      {error ? <div className="delivery-uber__toast is-error">{error}</div> : null}

      <section className={`delivery-uber__sheet ${activeDelivery ? "delivery-uber__sheet--active-trip" : ""}`}>
        <div className="delivery-uber__sheet-handle" />
        <div className="delivery-uber__sheet-head">
          {sheetHead || (
            <>
              <span className="delivery-uber__brand-mark">Yala Delivery</span>
              <h1>{sheetTitle}</h1>
              {sheetSubtitle ? <p>{sheetSubtitle}</p> : null}
            </>
          )}
        </div>
        <div className="delivery-uber__sheet-body">
          {!activeDelivery && todayEarnings ? (
            <div className="delivery-uber__earnings-card">
              <small>Today&apos;s earnings</small>
              <strong>{todayEarnings.amount} MRU</strong>
              <span>{todayEarnings.count} deliveries</span>
            </div>
          ) : null}
          {children}
        </div>
      </section>

      {showNav ? (
        <nav className="delivery-uber__nav" aria-label="Delivery navigation">
          <button
            type="button"
            className={`delivery-uber__nav-btn ${activeNav === "home" ? "is-active" : ""}`}
            onClick={() => {
              window.location.href = "/delivery/courier";
            }}
          >
            <span className="delivery-uber__nav-icon">⌂</span>
            <span>Home</span>
          </button>
          <button
            type="button"
            className={`delivery-uber__nav-btn ${activeNav === "orders" ? "is-active" : ""}`}
            onClick={() => {
              window.location.href = "/delivery/history";
            }}
          >
            <span className="delivery-uber__nav-icon">☰</span>
            <span>Orders</span>
          </button>
          <button
            type="button"
            className={`delivery-uber__nav-btn ${activeNav === "earnings" ? "is-active" : ""}`}
            onClick={() => {
              window.location.href = "/delivery/earnings";
            }}
          >
            <span className="delivery-uber__nav-icon">$</span>
            <span>Earnings</span>
          </button>
          <button
            type="button"
            className={`delivery-uber__nav-btn ${activeNav === "wallet" ? "is-active" : ""}`}
            onClick={() => {
              window.location.href = "/delivery/wallet";
            }}
          >
            <span className="delivery-uber__nav-icon">👛</span>
            <span>Wallet</span>
          </button>
          <button
            type="button"
            className={`delivery-uber__nav-btn ${activeNav === "profile" ? "is-active" : ""}`}
            onClick={() => {
              window.location.href = "/delivery/account";
            }}
          >
            <span className="delivery-uber__nav-icon">☺</span>
            <span>Profile</span>
          </button>
        </nav>
      ) : null}
    </main>
  );
}
