import React, { useCallback, useEffect, useState } from "react";

import { API_URL } from "../apiConfig";
import { apiRequest } from "./DeliveryShared";
import { DeliveryUberPage } from "./DeliveryUberLayout";
import "./delivery-uber.css";

export default function DeliveryCourierEarnings() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      setLoading(true);
      setData(await apiRequest(`${API_URL}/deliveries/courier/earnings/`));
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const today = data?.today || { earnings: "0", count: 0, commission: "0" };
  const week = data?.week || { earnings: "0", count: 0, commission: "0" };
  const month = data?.month || { earnings: "0", count: 0, commission: "0" };
  const wallet = data?.wallet || {};
  const history = data?.history || [];

  const requestPayout = () => {
    window.location.href = "/delivery/bank";
  };

  return (
    <DeliveryUberPage title="Earnings" onBack={() => (window.location.href = "/delivery/courier")}>
      <div className="delivery-uber__earnings">
        {error ? <p className="delivery-uber__toast is-error">{error}</p> : null}
        {loading ? <p className="delivery-uber__empty">Loading earnings...</p> : null}

        <div className="delivery-uber__earnings-grid">
          <article className="delivery-uber__earnings-card is-highlight">
            <small>Available balance</small>
            <strong>{Number(wallet.available_balance || 0).toFixed(0)} MRU</strong>
            <span>Wallet: {Number(wallet.wallet_balance || 0).toFixed(0)} MRU</span>
          </article>
          <article className="delivery-uber__earnings-card">
            <small>Pending</small>
            <strong>{Number(wallet.pending_balance || 0).toFixed(0)} MRU</strong>
            <span>{wallet.completed_deliveries || 0} completed</span>
          </article>
          <article className="delivery-uber__earnings-card">
            <small>Today</small>
            <strong>{Number(today.earnings).toFixed(0)} MRU</strong>
            <span>{today.count} deliveries</span>
          </article>
        </div>

        <button type="button" className="delivery-uber__primary-btn" style={{ width: "100%", marginBottom: 16 }} onClick={requestPayout}>
          Request payout
        </button>

        <div className="delivery-uber__earnings-grid">
          <article className="delivery-uber__earnings-card">
            <small>This week</small>
            <strong>{Number(week.earnings).toFixed(0)} MRU</strong>
            <span>{week.count} deliveries</span>
          </article>
          <article className="delivery-uber__earnings-card">
            <small>This month</small>
            <strong>{Number(month.earnings).toFixed(0)} MRU</strong>
            <span>{month.count} deliveries</span>
          </article>
        </div>

        <div className="delivery-uber__summary-card">
          <h3>Yala commission breakdown</h3>
          <div className="delivery-uber__summary-row">
            <span>Today commission</span>
            <strong>{Number(today.commission).toFixed(0)} MRU</strong>
          </div>
          <div className="delivery-uber__summary-row">
            <span>Month commission</span>
            <strong>{Number(month.commission).toFixed(0)} MRU</strong>
          </div>
          <div className="delivery-uber__summary-row">
            <span>Your share</span>
            <strong className="is-green">{Number(month.earnings).toFixed(0)} MRU</strong>
          </div>
        </div>

        <h3 className="delivery-uber__section-title">Delivery history</h3>
        <div className="delivery-uber__history-list">
          {history.length === 0 ? <p className="delivery-uber__empty">No completed deliveries yet.</p> : null}
          {history.map((delivery) => (
            <article key={delivery.id} className="delivery-uber__history-item">
              <div>
                <strong>#{delivery.id} · {delivery.pickup}</strong>
                <p>{delivery.destination}</p>
              </div>
              <div className="delivery-uber__history-meta">
                <strong>{Number(delivery.driver_earning || delivery.fare).toFixed(0)} MRU</strong>
                <span>{delivery.service_city || "Nouakchott"}</span>
              </div>
            </article>
          ))}
        </div>
      </div>
    </DeliveryUberPage>
  );
}
